export const servicePageKeys = Object.keys(servicePages) as ServicePageKey[];

export function servicePath(key: ServicePageKey, lang: ServiceLang) {
  const page = servicePages[key];
  return lang === "kz" ? `/kz/${page.slug.kz}` : `/${page.slug.ru}`;
}

export function localizedText(value: Localized, lang: ServiceLang) {
  return value[lang];
}
